 87	                UPDATE customer_order SET status = :status, payment_transaction_id = :tx, paid_at = :paidAt
 88	                WHERE id = :id
 89	                """)
 90	                .param("status", OrderStatus.PAID.name())
 91	                .param("tx", transactionId)
 92	                .param("paidAt", utc(paidAt))
 93	                .param("id", id)
 94	                .update();
 95	    }
