100	                .param("tracking", trackingCode)
101	                .param("id", id)
102	                .update();
103	    }
104	
105	    public Optional<PaymentNoticeOutcome> findPaymentNotice(String orderId, String transactionId) {
106	        return jdbc.sql("SELECT outcome FROM payment_notice WHERE order_id = :id AND transaction_id = :tx")
107	                .param("id", orderId)
108	                .param("tx", transactionId)
109	                .query((rs, n) -> PaymentNoticeOutcome.valueOf(rs.getString("outcome")))
110	                .optional();
111	    }
112	
113	    public void savePaymentNotice(String orderId, String transactionId, PaymentNoticeOutcome outcome) {
114	        jdbc.sql("INSERT INTO payment_notice (order_id, transaction_id, outcome) VALUES (:id, :tx, :outcome)")
115	                .param("id", orderId)
116	                .param("tx", transactionId)
117	                .param("outcome", outcome.name())
118	                .update();
119	    }
120	
121	    @Override
122	    public boolean hasPurchased(String cpf) {
123	        return jdbc.sql("SELECT COUNT(*) FROM customer_order WHERE cpf = :cpf AND status IN (:statuses)")
124	                .param("cpf", cpf)
125	                .param("statuses", Arrays.stream(OrderStatus.values())
126	                        .filter(OrderStatus::paymentSettled).map(OrderStatus::name).toList())
127	                .query(Long.class)
128	                .single() > 0;
129	    }
130	
131	    private Optional<Order> find(String sql, String id) {
132	        return jdbc.sql(sql).param("id", id).query(this::map).optional();
133	    }
134	
135	    private Order map(ResultSet rs, int rowNum) throws SQLException {
136	        String id = rs.getString("id");
137	        CheckoutSummary summary = new CheckoutSummary(
138	                money(rs, "products_subtotal"),
139	                money(rs, "coupon_discount"),
140	                money(rs, "shipping_cost"),
141	                rs.getInt("delivery_days"),
142	                money(rs, "insurance"),
143	                money(rs, "payment_adjustment"),
144	                money(rs, "final_total"),
145	                rs.getInt("installments"),
146	                money(rs, "installment_amount"),
147	                money(rs, "next_purchase_credit"),
148	                rs.getBoolean("gift"));
149	        return new Order(
150	                id,
151	                rs.getString("cpf"),
152	                rs.getString("email"),
153	                OrderStatus.valueOf(rs.getString("status")),
154	                rs.getObject("created_at", OffsetDateTime.class).toInstant(),
155	                summary,
156	                items(id),
157	                rs.getString("tracking_code"));
158	    }
159	
160	    private List<OrderItem> items(String orderId) {
161	        return jdbc.sql("SELECT sku, quantity FROM order_item WHERE order_id = :id ORDER BY line_no")
162	                .param("id", orderId)
163	                .query((rs, n) -> new OrderItem(rs.getString("sku"), rs.getInt("quantity")))
164	                .list();
165	    }
166	
167	    private static BigDecimal money(ResultSet rs, String column) throws SQLException {
168	        return Money.round(rs.getBigDecimal(column));
169	    }
170	
171	    private static OffsetDateTime utc(Instant instant) {
172	        return instant.atOffset(ZoneOffset.UTC);
173	    }
174	}
