 82	import java.util.Comparator;
 83	import java.util.List;
 84	import java.util.Map;
 85	
 86	import org.springframework.stereotype.Service;
 87	import org.springframework.transaction.annotation.Propagation;
 88	import org.springframework.transaction.annotation.Transactional;
 89	
 90	import com.loja.orders.order.OrderItem;
 91	
 92	/**
 93	 * Baixa e devolução de estoque. As linhas dos produtos ficam travadas até o fim da transação, então
 94	 * dois pagamentos simultâneos da última peça nunca baixam o mesmo estoque duas vezes.
 95	 */
 96	@Service
 97	public class InventoryService {
 98	
 99	    private final ProductRepository products;
100	
101	    public InventoryService(ProductRepository products) {
102	        this.products = products;
103	    }
104	
105	    /** Baixa o estoque de todos os itens, ou de nenhum se faltar algum. */
106	    @Transactional(propagation = Propagation.MANDATORY)
107	    public boolean take(List<OrderItem> items) {
108	        List<OrderItem> sorted = sortedBySku(items);
109	        Map<String, Integer> stock = products.lockStock(sorted.stream().map(OrderItem::sku).toList());
110	        boolean available = sorted.stream()
111	                .allMatch(item -> stock.getOrDefault(item.sku(), 0) >= item.quantity());
112	        if (!available) {
113	            return false;
114	        }
115	        sorted.forEach(item -> products.changeStock(item.sku(), -item.quantity()));
116	        return true;
117	    }
118	
119	    @Transactional(propagation = Propagation.MANDATORY)
120	    public void giveBack(List<OrderItem> items) {
121	        List<OrderItem> sorted = sortedBySku(items);
122	        products.lockStock(sorted.stream().map(OrderItem::sku).toList());
123	        sorted.forEach(item -> products.changeStock(item.sku(), item.quantity()));
124	    }
125	
126	    private static List<OrderItem> sortedBySku(List<OrderItem> items) {
127	        return items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
128	    }
129	}
